	xe_gt_pagefault_reset(gt);

	xe_uc_stop(&gt->uc);

	xe_tlb_inval_reset(&gt->tlb_inval);

	err = do_gt_reset(gt);
	if (err)
		goto err_out;

	err = do_gt_restart(gt);
	if (err)
		goto err_out;

	xe_force_wake_put(gt_to_fw(gt), fw_ref);
	xe_pm_runtime_put(gt_to_xe(gt));

	xe_gt_info(gt, "reset done\n");

